package org.apache.commons.math.fraction;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Fraction_compareTo_TriageGen5Test {







    @Test
    public void testCompareTo_NegativeValues() {
        // Testing with negative values
        // -1/2 (-0.5) vs -1/4 (-0.25) -> -0.5 < -0.25
        Fraction f1 = new Fraction(-1, 2);
        Fraction f2 = new Fraction(-1, 4);
        assertEquals(-1, f1.compareTo(f2));

        // -1/4 (-0.25) vs -1/2 (-0.5) -> -0.25 > -0.5
        assertEquals(1, f2.compareTo(f1));
    }




}

package org.apache.commons.math.fraction;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Fraction_compareTo_TriageGen5Test {









    @Test
    public void testCompareTo_Zero() {
        // Zero comparison
        Fraction zero = new Fraction(0, 1);
        Fraction positive = new Fraction(1, 1);
        Fraction negative = new Fraction(-1, 1);

        assertEquals(-1, zero.compareTo(positive));
        assertEquals(1, zero.compareTo(negative));
        assertEquals(0, zero.compareTo(zero));
    }


}

package org.apache.commons.math.fraction;

import java.io.*;
import java.math.*;
