import static org.junit.Assert.*;

public class Fraction_compareTo_TriageGen5Test {











    @Test
    public void testCompareTo_LargeValues() {
        // Testing large floating point values via Fraction
        Fraction f1 = new Fraction(1000000, 1);
        Fraction f2 = new Fraction(2000000, 1);
        assertEquals(-1, f1.compareTo(f2));
        assertEquals(1, f2.compareTo(f1));
    }
}
